CREATE OR REPLACE VIEW innovation_demo.v_call_pipeline AS SELECT c.call_code,c.focus_area,c.status AS call_status,COUNT(p.proposal_id) AS proposal_count,COUNT(p.proposal_id) FILTER(WHERE p.status='accepted') AS accepted_count FROM innovation_demo.calls c LEFT JOIN innovation_demo.proposals p USING(call_id) GROUP BY c.call_code,c.focus_area,c.status;
CREATE OR REPLACE VIEW innovation_demo.v_milestone_tracker AS SELECT p.project_ref,p.status AS project_status,m.milestone_ref,m.title,m.due_date,m.status,m.evidence_ref FROM innovation_demo.milestones m JOIN innovation_demo.projects p USING(project_id);
CREATE OR REPLACE VIEW innovation_demo.v_overdue_milestones AS SELECT * FROM innovation_demo.v_milestone_tracker WHERE due_date<CURRENT_DATE AND status NOT IN('completed','cancelled');